import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788439235000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>Everything mcp-hub reads from its own environment. Variables referenced as <code>\${VAR}</code> from <code>mcp.json</code> are separate — those are your servers&#39; secrets and are described under <a href="/guide/configuration#environment-expansion">configuration</a>.</p><h2 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to “Required”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>EXTERNAL_URL</code></td><td>The public base URL exactly as clients see it, e.g. <code>https://mcp.example.net</code>. No trailing path. Every OAuth metadata document, redirect and resource identifier is derived from it. Missing → the process exits at startup.</td></tr><tr><td><code>PASSWORD_HASH</code> <em>or</em> <code>PASSWORD</code></td><td>The login secret. <code>PASSWORD_HASH</code> takes precedence and is what you should use.</td></tr></tbody></table><p>Generate the hash with:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">htpasswd</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -bnBC</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> 10</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &quot;&quot;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;yourpassword&#39;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> tr</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -d</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> &#39;:\\n&#39;</span></span></code></pre></div><p><code>PASSWORD</code> compares in constant time, but it puts the plain-text secret in the container&#39;s environment where every child process and <code>docker inspect</code> can see it. Use it only for a throwaway test.</p><h2 id="recommended" tabindex="-1">Recommended <a class="header-anchor" href="#recommended" aria-label="Permalink to “Recommended”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>TRUSTED_PROXIES</code></td><td><em>(unset)</em></td><td>Comma-separated IPs/CIDRs allowed to set <code>X-Forwarded-*</code>. Decides what <code>req.ip</code> is, and therefore what the login rate limiter counts. Unset → a startup warning and per-IP limiting degrades to one global counter. See <a href="/guide/security#trusted-proxies">Security</a>.</td></tr><tr><td><code>RESOURCE_BOUND_TOKENS</code></td><td><code>true</code></td><td>RFC 8707 resource binding: a token is valid only for <code>/hub</code> (which covers <code>/health</code>) or the one <code>/&lt;name&gt;/mcp</code> it was issued for. <code>false</code>/<code>0</code> restores the pre-0.5 behaviour where unbound tokens reach every path — a migration mode that logs a warning on every start.</td></tr><tr><td><code>DEFAULT_RESOURCE</code></td><td><em>(unset)</em></td><td>Server name (or <code>hub</code>) to bind a token to when the OAuth client sends <strong>no</strong> <code>resource</code> parameter at all (older Codex logins, Google ADK, Gemini Enterprise). Unset → such requests are refused with <code>invalid_target</code>. The token is still bound either way — never global.</td></tr></tbody></table><h2 id="client-registration" tabindex="-1">Client registration <a class="header-anchor" href="#client-registration" aria-label="Permalink to “Client registration”">​</a></h2><p>See <a href="/guide/client-registration">Client registration</a> for what these do.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CLIENT_REGISTRATION</code></td><td><code>cimd,dcr</code></td><td>Which mechanisms a client may use to obtain a <code>client_id</code>, comma-separated. <code>cimd</code> = <a href="/guide/client-registration#client-id-metadata-documents">Client ID Metadata Documents</a>, <code>dcr</code> = <a href="/guide/client-registration#dynamic-client-registration">RFC 7591 dynamic registration</a>. Dropping <code>dcr</code> removes <code>registration_endpoint</code> from the discovery document and makes <code>/register</code> answer <code>404</code>; dropping <code>cimd</code> removes <code>client_id_metadata_document_supported</code> and treats a URL <code>client_id</code> as unknown. An unknown value exits at startup.</td></tr><tr><td><code>CIMD_ALLOWED_ORIGINS</code></td><td><em>(unset)</em></td><td>Comma-separated bare https origins whose metadata documents are accepted, e.g. <code>https://chatgpt.com,https://vscode.dev</code>. Unset → every https origin is admitted and the consent page is the gate. Only origins can be pinned: ChatGPT&#39;s per-connector document path is random. An entry that is not a bare origin exits at startup.</td></tr><tr><td><code>CIMD_ALLOW_PRIVATE_ADDRESSES</code></td><td><code>false</code></td><td>Local development only. Lets metadata documents be fetched from private, loopback and link-local addresses. Logs a warning on every start — leaving it on in production is what a <code>client_id</code> aimed at your internal network or a cloud metadata endpoint needs to succeed.</td></tr><tr><td><code>DCR_MAX_CLIENTS</code></td><td><code>500</code></td><td>Ceiling on stored dynamic registrations. When it is reached the hub evicts the oldest never-approved ones; if every registration under the ceiling has been approved, a new registration is refused rather than a working connector being dropped. Only applies to dynamic registration — metadata documents are never stored.</td></tr><tr><td><code>DCR_PENDING_TTL_HOURS</code></td><td><code>24</code></td><td>How long a registration may sit without ever being approved before it is removed. Opening the authorization page counts as use and starts the window again, so a slow login is not cut short.</td></tr><tr><td><code>DCR_INACTIVE_DAYS</code></td><td><code>90</code></td><td>How long an approved registration may sit unused before it is removed together with its approval and refresh tokens. Use means an authorization or a token exchange. Approvals for metadata-document clients are left alone.</td></tr></tbody></table><h2 id="sandboxed-servers" tabindex="-1">Sandboxed servers <a class="header-anchor" href="#sandboxed-servers" aria-label="Permalink to “Sandboxed servers”">​</a></h2><p>Only relevant with <code>type: &quot;docker&quot;</code> entries — see <a href="/guide/sandboxing">sandboxing</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>DOCKER_HOST</code></td><td><em>(required with Docker servers)</em></td><td>The <strong>policy proxy&#39;s</strong> socket, e.g. <code>unix:///run/proxy/docker.sock</code>. Missing values and direct <code>/var/run/docker.sock</code> access fail closed; other endpoints must pass the versioned proxy handshake.</td></tr></tbody></table><p>The proxy image (<code>ghcr.io/ni-c/mcp-hub-docker-proxy</code>) reads its own set:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CONFIG_PATH</code></td><td><code>/config/mcp.json</code></td><td>The same file the hub reads — mount its <strong>directory</strong> read-only (<code>./config:/config:ro</code>), like the hub does. It <em>is</em> the policy. Parsed without <code>\${VAR}</code> expansion — the proxy holds none of the hub&#39;s secrets.</td></tr><tr><td><code>LISTEN_SOCKET</code></td><td><code>/run/proxy/docker.sock</code></td><td>Unix socket the hub connects to. Shared with the hub through a volume.</td></tr><tr><td><code>DOCKER_SOCKET</code></td><td><code>/var/run/docker.sock</code></td><td>The real daemon.</td></tr><tr><td><code>SANDBOX_SECRETS_DIR</code></td><td><code>/run/secrets</code></td><td>Where <code>&quot;secretsFrom&quot;: &quot;x&quot;</code> looks for <code>x.env</code>. Files must be regular, non-symlink, at most 64 KiB, mode 640 or stricter, with at most 100 unique non-NUL entries.</td></tr><tr><td><code>SANDBOX_SECRETS_WATCH</code></td><td><code>true</code></td><td>Watch referenced secret files and recreate the affected sandbox when their content changes. Set to <code>false</code> to apply secret changes only on the next container create.</td></tr><tr><td><code>SOCKET_MODE</code></td><td><code>0660</code></td><td>Permissions of <code>LISTEN_SOCKET</code>. Group access is how the hub gets in; world-writable would hand the policy to anyone on the host.</td></tr><tr><td><code>LOG_FILE</code></td><td><em>(unset)</em></td><td>Same mirroring as the hub&#39;s, useful because refusals are logged as <code>DENY</code>.</td></tr></tbody></table><h2 id="limits-and-timeouts" tabindex="-1">Limits and timeouts <a class="header-anchor" href="#limits-and-timeouts" aria-label="Permalink to “Limits and timeouts”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>MCP_BODY_LIMIT</code></td><td><code>1mb</code></td><td>Maximum JSON body for authenticated MCP requests. Any Express/<code>bytes</code> size string.</td></tr><tr><td><code>MCP_REQUESTS_PER_MINUTE</code></td><td><code>120</code></td><td>MCP requests per minute <strong>per OAuth client</strong>. Positive integer.</td></tr><tr><td><code>MCP_MAX_CONCURRENT_REQUESTS</code></td><td><code>4</code></td><td>In-flight MCP requests per OAuth client — <code>POST</code>s carrying JSON-RPC, so this is the work a child server is doing at once. Positive integer.</td></tr><tr><td><code>MCP_MAX_CONCURRENT_STREAMS</code></td><td><code>32</code></td><td>Open listening streams per OAuth client: a 2025-era <code>GET</code>, or a <code>2026-07-28</code> <a href="/guide/subscriptions"><code>subscriptions/listen</code></a> <code>POST</code> whose response stays open. Both are the standing channel rather than work in progress, so neither is charged to the budget above. Bounds how many sessions one client may hold open, not how much work it may cause. Positive integer.</td></tr><tr><td><code>MCP_CALL_TIMEOUT_MS</code></td><td><code>300000</code></td><td>Deadline for one forwarded tool call or request. Raise it only for a deployment that genuinely runs long tools; a stuck call holds one of the concurrency slots above.</td></tr><tr><td><code>MCP_RESET_TIMEOUT_ON_PROGRESS</code></td><td><code>false</code></td><td>Whether a progress notification restarts that deadline. <code>true</code> is convenient for long tools and gives up the absolute bound: a child that emits progress forever keeps the call open forever.</td></tr><tr><td><code>IDLE_TIMEOUT_MINUTES</code></td><td><code>60</code></td><td>Minutes of inactivity before an <a href="/guide/on-demand">on-demand server</a> is put to sleep. <code>0</code> disables on-demand lifecycling entirely — every server starts at boot and keeps running, the pre-0.9 behaviour. Per-server <code>idleMinutes</code> overrides it.</td></tr><tr><td><code>HTTP_HEADERS_TIMEOUT_MS</code></td><td><code>10000</code></td><td>Node&#39;s header timeout.</td></tr><tr><td><code>HTTP_REQUEST_TIMEOUT_MS</code></td><td><code>310000</code></td><td>Complete request timeout — slightly above the default tool-call timeout. Your reverse proxy must allow at least as long, and raising <code>MCP_CALL_TIMEOUT_MS</code> means raising this and the proxy with it. A <code>subscriptions/listen</code> stream is exempt: it is idle by design and would otherwise be cut every few minutes, which looks exactly like a flaky upstream and is not. Its lifetime is bounded by <code>MCP_SUBSCRIPTION_MAX_MS</code> instead — and your reverse proxy needs a matching read timeout.</td></tr></tbody></table><h2 id="elicitation" tabindex="-1">Elicitation <a class="header-anchor" href="#elicitation" aria-label="Permalink to “Elicitation”">​</a></h2><p>What the hub will carry when a server asks the person at the far end a question. Full behaviour: <a href="/guide/elicitation">Elicitation</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MCP_ELICITATION</code></td><td><code>true</code></td><td>The whole feature. <code>false</code> is the emergency brake for every server at once; per server, use <code>&quot;passthrough&quot;: &quot;off&quot;</code> in <code>mcp.json</code>.</td></tr><tr><td><code>MCP_ELICITATION_MAX_ROUNDS</code></td><td><code>8</code></td><td>How often one tool call may come back for more input. The hub keeps nothing between requests, so the count travels inside the sealed state. Each round is a fresh call the caller pays for.</td></tr><tr><td><code>MCP_ELICITATION_STATE_TTL_MS</code></td><td><code>900000</code></td><td>How long a half-finished call stays resumable.</td></tr><tr><td><code>MCP_ELICITATION_MAX_MESSAGE_BYTES</code></td><td><code>4096</code></td><td>One prompt, measured in bytes. It is read by a person; anything longer is not a prompt. Oversized text is truncated, not refused.</td></tr><tr><td><code>MCP_ELICITATION_MAX_PAYLOAD_BYTES</code></td><td><code>131072</code></td><td>The whole question including its schemas. Over this the call is refused rather than trimmed — there is no way to shorten a schema safely.</td></tr></tbody></table><p>These five are read by the request path, so an unusable value logs and keeps the default.</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to “Diagnostics”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MCP_DIAGNOSTICS</code></td><td><code>false</code></td><td>Adds <a href="/reference/hub-tools#describe-connection"><code>describe_connection</code></a> to <code>/hub</code>, a seventh meta-tool that reports how the caller is connected. Off because every tool a client can see costs context in every conversation it has, and most deployments never need to ask. Read per request.</td></tr></tbody></table><p>The switch is about context cost, not safety. The tool reports only what the caller&#39;s own request already carried and says nothing about any other client — which is why it exists in place of a tool that hands out the hub&#39;s log. That log carries upstream URLs, internal hostnames and text written by the children; serving it through <code>/hub</code> would let any registered connector read what every other connector is doing.</p><h2 id="subscriptions" tabindex="-1">Subscriptions <a class="header-anchor" href="#subscriptions" aria-label="Permalink to “Subscriptions”">​</a></h2><p>What a client may watch, and how much of it the hub will hold open. See <a href="/guide/subscriptions">Subscriptions</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MCP_SUBSCRIPTIONS</code></td><td><code>true</code></td><td>The whole feature. <code>false</code> is the emergency brake for every server at once; per server, use <code>&quot;subscriptions&quot;: &quot;off&quot;</code> in <code>mcp.json</code>.</td></tr><tr><td><code>MCP_MAX_SUBSCRIPTIONS</code></td><td><code>1024</code></td><td>Open <code>subscriptions/listen</code> streams one route will serve before refusing the next.</td></tr><tr><td><code>MCP_SUBSCRIPTION_MAX_URIS</code></td><td><code>64</code></td><td>Resource URIs one filter may name. Every URI is an upstream subscription the hub holds and reconciles, so an unbounded list is a way to make it do unbounded work on one request. Over this the call is refused with <code>-32602</code>.</td></tr><tr><td><code>MCP_SUBSCRIPTION_KEEPALIVE_MS</code></td><td><code>15000</code></td><td>SSE keepalive on a listen stream; <code>0</code> disables it.</td></tr><tr><td><code>MCP_SUBSCRIPTION_DEBOUNCE_MS</code></td><td><code>250</code></td><td>Coalescing window. Within it, repeats of the same event collapse to one — which is what the notification means anyway: read it again, not here is what changed. <code>0</code> delivers each event as it arrives.</td></tr><tr><td><code>MCP_SUBSCRIPTION_MAX_MS</code></td><td><code>1800000</code></td><td>How long one stream may stay open before the hub closes it; <code>0</code> means as long as the socket lives. A reaper for clients that go away without closing anything.</td></tr></tbody></table><p>These six are read by the request path as well, with the same fallback behaviour. A listen stream is charged to <code>MCP_MAX_CONCURRENT_STREAMS</code>, not <code>MCP_MAX_CONCURRENT_REQUESTS</code>.</p><p>An invalid value for any of the integer variables read at startup aborts with a clear message rather than silently falling back. The two call-timeout variables are the exception: they are read by the request path itself, so an unusable value logs and keeps the hardened default instead of taking the hub down.</p><h2 id="paths" tabindex="-1">Paths <a class="header-anchor" href="#paths" aria-label="Permalink to “Paths”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CONFIG_PATH</code></td><td><code>/config/mcp.json</code></td><td>The <code>mcpServers</code> config file. Watched for changes — mount its <strong>directory</strong> (<code>./config:/config:ro</code>), not the file: a single-file bind mount misses rename-style editor saves and logs a startup warning.</td></tr><tr><td><code>DATA_PATH</code></td><td><code>/data</code></td><td>JWT key, OAuth clients, approvals, refresh tokens. Must be persistent.</td></tr><tr><td><code>TOOL_CACHE_PATH</code></td><td><code>&lt;DATA_PATH&gt;/tool-cache.json</code></td><td>Snapshots (identity, capabilities, tool list) of <a href="/guide/on-demand">on-demand servers</a>, so they can boot into <code>sleeping</code> instead of warm-starting. Not writable → a startup warning and on-demand servers warm-start at every boot.</td></tr><tr><td><code>LOG_FILE</code></td><td><em>(unset)</em></td><td>Mirror every hub log line into this file with an ISO-8601 UTC prefix, in addition to the console. See <a href="/guide/deployment#fail2ban">fail2ban</a>.</td></tr><tr><td><code>PORT</code></td><td><code>80</code> in the image, <code>3000</code> otherwise</td><td>Listen port.</td></tr></tbody></table><p><code>DATA_PATH</code> is also read by <code>mcp-hub-admin</code>, so the admin CLI needs it set to the same directory when run outside the container.</p><h2 id="in-stdio-mode" tabindex="-1">In stdio mode <a class="header-anchor" href="#in-stdio-mode" aria-label="Permalink to “In stdio mode”">​</a></h2><p><code>--stdio</code> (<a href="/guide/clients#local-clients-over-stdio">local clients</a>) starts no listener and no authorization server, so most of the table above does not apply. What it reads:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CONFIG_PATH</code></td><td><code>mcp.json</code> in the working directory</td><td>Same file, same hot reload. A missing file starts an empty hub instead of failing — the client that spawned the process has nowhere to show a startup error.</td></tr><tr><td><code>IDLE_TIMEOUT_MINUTES</code></td><td><code>60</code></td><td>As above. Worth keeping on: a hub spawned per client session would otherwise start every configured server at every launch.</td></tr><tr><td><code>TOOL_CACHE_PATH</code></td><td><code>.mcp-hub/tool-cache.json</code> beside the config</td><td>As above, but there is no <code>DATA_PATH</code> here to derive it from.</td></tr><tr><td><code>DATA_PATH</code></td><td><em>(unset)</em></td><td>Optional here, unlike over HTTP. Point it at an HTTP hub&#39;s <code>/data</code> to reuse and refresh an <a href="/guide/configuration#upstreams-that-speak-oauth">upstream OAuth token</a> authorized there. Without it, a server with an <code>oauth</code> block is skipped — there is no listener for a browser to return to.</td></tr><tr><td><code>LOG_FILE</code></td><td><em>(unset)</em></td><td>Same as above. Logging otherwise goes to stderr: in stdio mode stdout carries the protocol, so <code>console.log</code> output is moved out of the way.</td></tr></tbody></table><p>Everything else — <code>EXTERNAL_URL</code>, <code>PASSWORD*</code>, <code>TRUSTED_PROXIES</code>, <code>RESOURCE_BOUND_TOKENS</code>, <code>DEFAULT_RESOURCE</code>, <code>PORT</code>, the rate limits and the HTTP timeouts — is HTTP-only and ignored. The call timeouts (<code>MCP_CALL_TIMEOUT_MS</code> and friends) apply, since they belong to the proxying path.</p><h2 id="full-compose-example" tabindex="-1">Full Compose example <a class="header-anchor" href="#full-compose-example" aria-label="Permalink to “Full Compose example”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">environment</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  EXTERNAL_URL</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;https://mcp.example.net&quot;</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  PASSWORD_HASH</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;\${PASSWORD_HASH}&quot;</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  TRUSTED_PROXIES</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;192.168.1.0/24&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  MCP_BODY_LIMIT</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;1mb&quot;</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  MCP_REQUESTS_PER_MINUTE</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;120&quot;</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  MCP_MAX_CONCURRENT_REQUESTS</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;4&quot;</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  MCP_MAX_CONCURRENT_STREAMS</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;32&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  LOG_FILE</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;/data/mcp-hub.log&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">  # Referenced as \${…} inside mcp.json:</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  PAPERLESS_API_TOKEN</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;\${PAPERLESS_API_TOKEN}&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Pass every <code>\${VAR}</code> your config references</p><p>A variable referenced in <code>mcp.json</code> may be <strong>empty</strong>, but if it is undefined the whole config fails to parse and no server starts. Declaring it in the Compose <code>environment:</code> block — with <code>\${VAR:-}</code> if it may be absent — avoids that.</p></div>`,41)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};